const b = $('Build Prompt').item.json;

const c = $('Call Input').item.json.contact || {};
const cf = id => { const f = (c.customFields || []).find(x => x.id === id); return f ? (f.value !== undefined ? f.value : f.field_value) : ''; };
const EVENTLOGS='7D9N71mEDfipN90zfV0j', CALLSUM='ZVeEoK85i5EOhWt1HO1F', INTERACT='AH3JqyYEPzPX4wXKoX1V', INSTID='TWLomDBX0XInU1IKrG8L';

let ai_outcome = '', summary = '', ai_resume = '';
try {
  const resp = $('OpenAI: Classify Call').item.json || {};
  let content = (resp.choices && resp.choices[0] && resp.choices[0].message) ? (resp.choices[0].message.content || '') : '';
  content = String(content).replace(/```json/gi,'').replace(/```/g,'').trim();
  const parsed = JSON.parse(content);
  ai_outcome = String(parsed.outcome || '').trim().toLowerCase();
  summary = String(parsed.summary || '').trim();
  ai_resume = String(parsed.resume_call_at || '').trim();
} catch(e) {}

const KNOWN = ['cold-good','cold-bad','cold-on-hold','gatekeeper-good','gatekeeper-bad','gatekeeper-on-hold','conversation-active','conversation-active-on-hold','appointment-booked','sales-call','not-interested-right-now-good','not-interested-right-now-bad','do-not-contact','voicemail','call-center','bad-number','not-a-fit'];
const disposition = String(b.disposition || '').trim().toLowerCase();

// disposition wins; AI outcome only when disposition missing/unrecognized. default = cold-good.
let outcome = 'cold-good';
if (KNOWN.indexOf(disposition) >= 0) outcome = disposition;
else if (KNOWN.indexOf(ai_outcome) >= 0) outcome = ai_outcome;

// DRIP outcomes -> continue the sequence (Send Cold Email N+1). voicemail = like a missed call.
// gatekeeper-good drips too; its NEXT call just lands in the gatekeeper lane (decided by the tag at 4:30AM).
const DRIP_OUTCOMES = ['cold-good','gatekeeper-good','voicemail'];
const continues_drip = DRIP_OUTCOMES.indexOf(outcome) >= 0;
const is_voicemail = (outcome === 'voicemail');

// Cold vs gatekeeper disposition drives the `gatekeeper` tag (which call lane the lead uses next).
const GATEKEEPER_DISP = ['gatekeeper-good','gatekeeper-bad','gatekeeper-on-hold'];
const COLD_DISP       = ['cold-good','cold-bad','cold-on-hold'];
const is_gatekeeper = GATEKEEPER_DISP.indexOf(outcome) >= 0;   // -> add tag
const is_cold       = COLD_DISP.indexOf(outcome) >= 0;         // -> remove tag
// Option A: only cold/gatekeeper dispositions touch the tag; everything else (voicemail, etc.) leaves it.
const tag_action = is_gatekeeper ? 'add' : (is_cold ? 'remove' : '');

// Cold Bad OR Gatekeeper Bad stops future phone calls (email drip continues)
const stop_phone_calls = (outcome === 'cold-bad' || outcome === 'gatekeeper-bad');

// everything else -> Client Acquisition, same-named stage
const CLIENT_ACQ = 'O7LMZpDOFM2SYO65twC5';
const CA_STAGE = {
  'cold-bad':                      '8ecc2327-779f-4250-8d54-4554b49087f9',
  'gatekeeper-bad':                'd5670151-b316-448b-8b13-c4f804fdd696',
  'call-center':                   '04546ed9-e0d9-47dc-b61e-c0cd820849d7',
  'gatekeeper-on-hold':            'e921913e-1530-4186-8ce8-bb3dab47d301',
  'cold-on-hold':                  '54994e3f-1643-46f4-8eeb-ade43712ae2d',
  'conversation-active':           'edca2ee6-569d-4486-9ecd-4110e9c32882',
  'conversation-active-on-hold':   '175c5765-fd68-48d5-a319-8bcc77487703',
  'appointment-booked':            '5344bfb7-9370-401e-8767-32bbdcc73778',
  'sales-call':                    '64251edf-6f9f-4b3e-b36b-3059814c2787',
  'not-interested-right-now-good': '8c76b904-fa25-4a73-9ac2-e17fb8323e2b',
  'not-interested-right-now-bad':  '865a3d8d-045d-4b5d-b421-4115b876bb25',
  'do-not-contact':                'cfc46631-06a5-4ef3-9788-1f15f35f052b',
  'bad-number':                    '298c5fad-72da-4628-b254-0c4df89c72e1',
  'not-a-fit':                     '1d34796e-811a-4bb3-afcb-61b59446a31e'
};

const EMAIL_PIPELINE = '1A1RkYaL93s2rqbQ3Opi';
const SEND_NEXT      = { 1:'e4b13f51-2229-4d47-aa3e-12381a31a8c1', 2:'342b193f-9456-4bcc-a2a7-cb81973500c9', 3:'f3ea4cd2-daf2-4ca2-baaa-301f807d697c' };
// Stop Emails: skip the cold-email send by moving straight to 'Cold Email N Sent' (4:30AM still drains it).
const SEND_NEXT_SENT = { 1:'fdd4f9a4-a626-4866-a904-5053e626306f', 2:'2f599547-4a2b-4ba4-850d-0feb7fcc976c', 3:'39a20e88-ce88-46c6-9e95-8134aa9f269d' };
const stop_emails = (String(cf('ixRO9dSUHVd6vNTdFa7Q') || '').trim() === 'True') || !String((c && c.email) || '').trim();  // no email on the contact -> skip every email step (route to Cold Email N Sent)
const N = parseInt(String(b.caller_N || 0), 10) || 0;

let target_pipeline_id = '', target_stage_id = '';
if (continues_drip) { target_pipeline_id = EMAIL_PIPELINE; target_stage_id = (stop_emails ? SEND_NEXT_SENT[N] : SEND_NEXT[N]) || ''; }
else { target_pipeline_id = CLIENT_ACQ; target_stage_id = CA_STAGE[outcome] || ''; }
const active_opp_id = String(b.opp_id || b.active_opp_id || '').trim();
const can_move = !!(active_opp_id && target_pipeline_id && target_stage_id);

const ON_HOLD = (outcome === 'cold-on-hold' || outcome === 'gatekeeper-on-hold' || outcome === 'conversation-active-on-hold');
let resume_call_at = '';
if (ON_HOLD) { const s = String(ai_resume || '').trim().replace('T', ' '); if (/^\d{4}-\d{2}-\d{2}( \d{2}:\d{2})?$/.test(s)) resume_call_at = s; }

let next_caller_stage = '';
if (outcome === 'cold-on-hold' || outcome === 'gatekeeper-on-hold') next_caller_stage = 'cold_call_' + ((N >= 1 && N <= 3) ? N : 1);
else if (outcome === 'conversation-active-on-hold') next_caller_stage = 'day_1_attempt_1';

const now = DateTime.now().setZone('America/Los_Angeles');
const stamp = now.toFormat('ccc, LLL d, yyyy, hh:mm a') + ' (PT)';
const resumeNote = resume_call_at ? (' | resume call at ' + resume_call_at) : '';
const stage_name = String(b.stage_name || '').trim();

// Call Summary line: "[stamp | <stage_name>] <AI summary>" (+ resume). Keeps the rich summary.
const csEntry = '[' + stamp + ' | ' + (stage_name || 'call') + '] ' + (summary || 'call completed') + resumeNote;
// Event Log line: "[stamp] <stage_name> <disposition>" — no resume suffix.
const elEntry = '[' + stamp + '] ' + (stage_name ? (stage_name + ' ') : '') + outcome;

// idempotent delta-replace: replace THIS call's prior line, else append. Preserves other writers.
const upsert = (live, lastEntry, newEntry) => {
  live = String(live || ''); lastEntry = String(lastEntry || '');
  if (lastEntry && live.indexOf(lastEntry) >= 0) return live.split(lastEntry).join(newEntry);
  return live ? (live + '\n' + newEntry) : newEntry;
};
const updated_event_logs   = upsert(cf(EVENTLOGS), b.last_event_log_entry,   elEntry);
const updated_call_summary = upsert(cf(CALLSUM),   b.last_call_summary_entry, csEntry);

let interaction_summary = summary || String(cf(INTERACT) || '').trim();
if (resume_call_at) interaction_summary = (interaction_summary + ' Next: resume call at ' + resume_call_at + '.').trim();

// sheet-safe text: USER_ENTERED reads a leading =,+,@,- as a formula (a leading ' forces text); a cell caps at 50k chars.
const sheetSafe = s => { s = String(s || '').trim(); if (/^[=+@-]/.test(s)) s = "'" + s; return s.length > 45000 ? (s.slice(0, 45000) + ' ...[truncated]') : s; };

return { json: {
  outcome: outcome, is_cold: is_cold, is_gatekeeper: is_gatekeeper, continues_drip: continues_drip, tag_action: tag_action, is_voicemail: is_voicemail, stop_emails: stop_emails, stop_phone_calls: stop_phone_calls,
  contact_id: String(b.contact_id || c.id || '').trim(),
  active_opp_id: active_opp_id, can_move: can_move,
  target_pipeline_id: target_pipeline_id, target_stage_id: target_stage_id,
  instantly_lead_id: String(cf(INSTID) || '').trim(),
  resume_call_at: resume_call_at,
  next_caller_stage: next_caller_stage,
  updated_call_summary: updated_call_summary, updated_event_logs: updated_event_logs, interaction_summary: interaction_summary,
  new_event_log_entry: elEntry, new_call_summary_entry: csEntry, signature: String(b.signature || ''),
  timestamp_pt: now.toFormat('yyyy-LL-dd HH:mm:ss'), date_pt: now.toFormat('yyyy-LL-dd'),
  company: String(b.company_name || '').trim(), city: String(c.city || '').trim(),
  pipeline: String(b.route || '').trim(), stage_name: stage_name,
  attempt_no: (N >= 1 && N <= 3) ? N : '',
  is_mgr: (String(cf('u9UymBEMP3f7IZqDTwVd') || '').trim() !== '') ? 'TRUE' : 'FALSE',
  is_missed_variant: (String(stage_name).indexOf('(missed call)') >= 0) ? 'TRUE' : 'FALSE',
  picked_up: 'TRUE',
  disposition_source: (b.is_fallback === true || String(b.is_fallback) === 'true') ? 'ai_fallback' : 'human',
  disposition_slug: disposition, ai_outcome: ai_outcome, final_outcome: outcome,
  call_id: String(b.call_id || '').trim(),
  call_duration: String(b.call_duration || '').trim(),
  call_recording_url: String(b.call_recording_url || '').trim(),
  call_transcript: sheetSafe(b.transcript)
}};

const P = $('Parse + Map Outcome').item.json;

// interaction summary: prefer the fresh AI rolling summary, else the Parse+Map fallback
let interaction = '';
try { interaction = String($('AI: Interaction Summary').item.json.choices[0].message.content || '').trim(); } catch(e) {}
interaction = interaction || P.interaction_summary;
const r = P.resume_call_at;
if (r && String(interaction).indexOf(r) < 0) interaction = (interaction + ' Next: resume call at ' + r + '.').trim();

// processing-state write-back (read next time by the Router / Capture)
const state = JSON.stringify({
  processed: true,
  last_event_log_entry: P.new_event_log_entry,
  last_call_summary_entry: P.new_call_summary_entry,
  last_signature: P.signature
});

const custom_fields = [
  { id: '7D9N71mEDfipN90zfV0j', value: P.updated_event_logs },      // Event Logs (delta-replaced)
  { id: 'ZVeEoK85i5EOhWt1HO1F', value: P.updated_call_summary },    // Call Summary (delta-replaced)
  { id: 'AH3JqyYEPzPX4wXKoX1V', value: interaction },               // Interaction Summary (overwrite)
  { id: 'u5VC5C59UlFZJDYOuw7N', value: r || '' },                   // Resume Call At (always; '' clears)
  { id: 'Tj0yopYbErXbwsTYTsCX', value: P.next_caller_stage || '' }, // Next Caller Stage (always; '' clears)
  { id: 'KFDw66sjfFaszQx5UX6X', value: P.stop_phone_calls ? 'True' : 'False' }, // Stop Phone Calls (always: True to stop, else False)
  { id: 'BD9TmgEynOEy6bCvZshm', value: state }                      // Call Processing State
];

return { json: { custom_fields: custom_fields } };

const P = $('Parse + Map Outcome').item.json;
const ci = $('Call Input').item.json;
const c = ci.contact || {};
const cf = id => { const f = (c.customFields || []).find(x => x.id === id); return f ? (f.value !== undefined ? f.value : f.field_value) : ''; };

// stage id comes from the Call Router Context Capture stored on the contact (HW0eBfoQPW2mwxX8aY7Q).
// The Router passes the whole contact through untouched, so we read it straight off the contact —
// no need for the Dispatcher to carry stage_id as a separate contract field.
let rctx = {}; try { rctx = JSON.parse(String(cf('HW0eBfoQPW2mwxX8aY7Q') || '{}')) || {}; } catch(e) {}
const stage_id = String(rctx.stage_id || '').trim();

// mc from the caller STAGE ID (same map as the missed-call Cold Handler's MCE_BY_STAGE):
// 1 = first miss (Day 1 Call A* / Day 2 first attempt); 2 = second miss of Day 2;
// 0 = no missed-call email (Day 1 Call B, all of Day 3).
const MCE_BY_STAGE = {
  'b9ce3091-acad-4067-abb5-49dc19ec4314': 1, // Day 1 Call A (from on hold)
  '042d9b81-1cb4-4265-a3c0-086b7d9d149d': 1, // Day 2 Call
  'cee93f24-aedb-45d1-a613-0bd4d3d326d7': 1, // Day 2 Call (MGR)
  'efda07de-f15a-48c1-b0dd-a84ad1f52899': 1, // Day 2 Call (from on hold)
  'a1d2058e-6fcf-4be5-8046-85fd1aff1fbc': 2, // Day 2 Call (missed call)
  'b7a81325-f410-4fa4-b5c7-a65fe6e3b284': 2  // Day 2 Call MGR (missed call)
};
const INTEREST = { 1: -29996, 2: -29992 };
const mce = MCE_BY_STAGE[stage_id] || 0;
const interest_value = INTEREST[mce] || 0;   // 0 => no missed-call email
const sends_email = interest_value !== 0;

return { json: {
  contact_id: String(P.contact_id || c.id || '').trim(),
  instantly_lead_id: String(P.instantly_lead_id || cf('TWLomDBX0XInU1IKrG8L') || '').trim(),
  email: String(c.email || ci.email || '').trim(),
  first_name: String(c.firstName || '').trim(),
  mc: String(mce || ''), interest_value: interest_value, sends_email: sends_email,
  stop_emails: ((String(cf('ixRO9dSUHVd6vNTdFa7Q') || '').trim() === 'True') || !String((c && c.email) || ci.email || '').trim())
}};
